export function checkIsDevMode() {
  if (typeof window === 'undefined') return false;

  try {
    const isViteDev = Boolean(typeof import.meta !== 'undefined' && import.meta.env && import.meta.env.DEV);
    const isEnvFlag = Boolean(typeof import.meta !== 'undefined' && import.meta.env && import.meta.env.VITE_DEV_MODE === 'true');
    const isLocalhost =
      window.location.hostname === 'localhost' ||
      window.location.hostname === '127.0.0.1' ||
      window.location.hostname === '[::1]';
    const isLocalStorageFlag = Boolean(window.localStorage && window.localStorage.getItem('DEV_MODE') === 'true');

    return isViteDev || isEnvFlag || isLocalhost || isLocalStorageFlag;
  } catch (_) {
    return false;
  }
}

export function normalizeText(str) {
  if (!str) return '';
  return str
    .trim()
    .replace(/\s+/g, ' ')
    .normalize('NFC')
    .toLowerCase();
}

export function cleanScriptText(str) {
  if (!str) return '';
  return str
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    .replace(/[.,\/#!$%\^&\*;:{}=\-_`~()?"'<>|[\]\\]/g, '')
    .trim()
    .replace(/\s+/g, ' ')
    .normalize('NFC')
    .toLowerCase();
}

export function getGraphemes(text) {
  if (!text) return [];
  if (typeof Intl !== 'undefined' && Intl.Segmenter) {
    const segmenter = new Intl.Segmenter(undefined, { granularity: 'grapheme' });
    return Array.from(segmenter.segment(text), (s) => s.segment);
  }
  return Array.from(text);
}

export function levenshteinDistance(a, b) {
  if (a.length === 0) return b.length;
  if (b.length === 0) return a.length;

  const matrix = [];
  for (let i = 0; i <= b.length; i++) matrix[i] = [i];
  for (let j = 0; j <= a.length; j++) matrix[0][j] = j;

  for (let i = 1; i <= b.length; i++) {
    for (let j = 1; j <= a.length; j++) {
      if (b.charAt(i - 1) === a.charAt(j - 1)) {
        matrix[i][j] = matrix[i - 1][j - 1];
      } else {
        matrix[i][j] = Math.min(
          matrix[i - 1][j - 1] + 1,
          matrix[i][j - 1] + 1,
          matrix[i - 1][j] + 1
        );
      }
    }
  }
  return matrix[b.length][a.length];
}

export function preprocessCanvasForOCR(canvas) {
  if (!canvas) {
    return {
      dataUrl: '',
      strokeMetrics: { width: 0, height: 0, aspectRatio: 1, drawnPixels: 0, horizontalSpan: 0 },
    };
  }

  const ctx = canvas.getContext('2d');
  const width = canvas.width;
  const height = canvas.height;
  const imgData = ctx.getImageData(0, 0, width, height);
  const data = imgData.data;

  let minX = width,
    minY = height,
    maxX = 0,
    maxY = 0;
  let drawnPixels = 0;

  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const idx = (y * width + x) * 4;
      const r = data[idx];
      const g = data[idx + 1];
      const b = data[idx + 2];
      const alpha = data[idx + 3];

      // Identify dark pixels of user handwriting
      if (alpha > 50 && (r < 190 || g < 190 || b < 190)) {
        drawnPixels++;
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
        if (y < minY) minY = y;
        if (y > maxY) maxY = y;
      }
    }
  }

  if (drawnPixels === 0 || maxX < minX || maxY < minY) {
    return {
      dataUrl: canvas.toDataURL('image/png'),
      strokeMetrics: { width: 0, height: 0, aspectRatio: 1, drawnPixels: 0, horizontalSpan: 0 },
    };
  }

  const strokeWidth = maxX - minX + 1;
  const strokeHeight = maxY - minY + 1;
  const aspectRatio = strokeWidth / strokeHeight;

  const padding = 35;
  const targetWidth = Math.max(280, strokeWidth + padding * 2);
  const targetHeight = Math.max(200, strokeHeight + padding * 2);

  const outCanvas = document.createElement('canvas');
  outCanvas.width = targetWidth;
  outCanvas.height = targetHeight;
  const outCtx = outCanvas.getContext('2d');

  outCtx.fillStyle = '#ffffff';
  outCtx.fillRect(0, 0, targetWidth, targetHeight);

  const destX = (targetWidth - strokeWidth) / 2;
  const destY = (targetHeight - strokeHeight) / 2;

  outCtx.drawImage(
    canvas,
    minX,
    minY,
    strokeWidth,
    strokeHeight,
    destX,
    destY,
    strokeWidth,
    strokeHeight
  );

  return {
    dataUrl: outCanvas.toDataURL('image/png'),
    strokeMetrics: {
      width: strokeWidth,
      height: strokeHeight,
      aspectRatio,
      drawnPixels,
      horizontalSpan: strokeWidth / width,
      verticalSpan: strokeHeight / height,
      boundingBox: { minX, minY, maxX, maxY },
    },
  };
}

/**
 * Evaluates handwriting OCR against target character/word.
 * Requires genuine OCR recognition of the target character/word.
 */
export function evaluateHandwriting({
  recognizedText,
  engOCRText,
  targetWord,
  safeLang,
  strokeMetrics,
  isSingleLetter,
}) {
  const normTarget = normalizeText(targetWord);
  const cleanTarget = cleanScriptText(targetWord);
  const normOCR = normalizeText(recognizedText);
  const cleanOCR = cleanScriptText(recognizedText);
  const normEng = normalizeText(engOCRText);
  const cleanEng = cleanScriptText(engOCRText);

  const targetGraphemes = getGraphemes(cleanTarget || normTarget);
  const targetCodeLen = (cleanTarget || normTarget).length;
  const targetGraphCount = targetGraphemes.length;

  const allCandidateTexts = Array.from(
    new Set([normOCR, cleanOCR, normEng, cleanEng].filter(Boolean))
  );

  if (allCandidateTexts.length === 0) {
    return {
      isMatch: false,
      reason: 'No text recognized by OCR from canvas',
      candidates: [],
    };
  }

  const candidateDetails = allCandidateTexts.map((txt) => {
    const cGraphemes = getGraphemes(txt);
    const dist = levenshteinDistance(txt, cleanTarget || normTarget);
    const exact = txt === normTarget || txt === cleanTarget || txt.toLowerCase() === normTarget.toLowerCase();
    const contains = txt.includes(cleanTarget) || txt.includes(normTarget) || (safeLang === 'en' && txt.toLowerCase().includes(normTarget.toLowerCase()));

    return {
      text: txt,
      graphemes: cGraphemes,
      graphemeCount: cGraphemes.length,
      distance: dist,
      exactMatch: exact,
      containsTarget: contains,
    };
  });

  // 1. Single Letter / Single Character Verification Rule
  if (isSingleLetter || targetGraphCount === 1 || targetCodeLen <= 1) {
    // English 'I' or 'l' specific stroke check
    if (normTarget.toLowerCase() === 'i' || normTarget === 'l' || normTarget === '1') {
      const verticalSymbols = ['i', 'I', 'l', '|', '1', '/', '!'];
      const ocrHasVertical = allCandidateTexts.some((txt) =>
        verticalSymbols.some((s) => txt.includes(s))
      );
      if (ocrHasVertical) {
        return {
          isMatch: true,
          reason: 'Letter "I" recognized',
          candidates: candidateDetails,
        };
      }
    }

    // Direct / Substring match for single character
    for (const cand of candidateDetails) {
      if (cand.exactMatch || cand.containsTarget) {
        return {
          isMatch: true,
          reason: `Character recognized by OCR: "${cand.text}"`,
          candidates: candidateDetails,
        };
      }
    }

    // Single character did not match target
    return {
      isMatch: false,
      reason: `Drawn shape did not match target "${targetWord}". OCR output: ${allCandidateTexts.join(', ') || 'none'}`,
      candidates: candidateDetails,
    };
  }

  // 2. Multi-character Word Verification
  for (const cand of candidateDetails) {
    // Exact Match
    if (cand.exactMatch) {
      return {
        isMatch: true,
        reason: `Exact word match: "${cand.text}"`,
        candidates: candidateDetails,
      };
    }

    // Substring inclusion (the full target word is contained within OCR output)
    if (cand.containsTarget) {
      return {
        isMatch: true,
        reason: `Target word found in OCR text: "${cand.text}"`,
        candidates: candidateDetails,
      };
    }

    // Fuzzy matching ONLY for words with 3+ graphemes where almost all characters match
    if (targetGraphCount >= 3 && cand.graphemeCount >= targetGraphCount - 1 && cand.distance <= 1) {
      // Check that at least 80% of target graphemes are present
      let matchedCount = 0;
      for (const tg of targetGraphemes) {
        if (cand.graphemes.includes(tg)) {
          matchedCount++;
        }
      }
      if (matchedCount / targetGraphCount >= 0.75) {
        return {
          isMatch: true,
          reason: `Word match with high confidence (${Math.round((matchedCount / targetGraphCount) * 100)}% graphemes): "${cand.text}"`,
          candidates: candidateDetails,
        };
      }
    }
  }

  return {
    isMatch: false,
    reason: `Handwriting did not match target word "${targetWord}". OCR recognized: ${allCandidateTexts.join(', ') || 'none'}`,
    candidates: candidateDetails,
  };
}
